function replaceOnce(src,from,to,label){const i=src.indexOf(from);if(i<0)throw new Error(`missing transform marker: ${label}`);if(src.indexOf(from,i+from.length)>=0)throw new Error(`ambiguous transform marker: ${label}`);return src.slice(0,i)+to+src.slice(i+from.length)}
function replaceAllChecked(src,from,to,min,label){const count=src.split(from).length-1;if(count<min)throw new Error(`missing transform markers ${label}: ${count}<${min}`);return src.split(from).join(to)}

